from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path
INSTALLER_VERSION="3.7.0-AUTONOMOUS-PROPERTY-BRAIN-INSTALLER"
MODULE_NAME="alliance_autonomous_property_brain_v370.py"
REGISTRAR="alliance_optional_property_modules.py"
MODULE_B64=''
MARKER="# FOUNDATION 3.7 - Autonomous Property Brain Teacher"
REGISTRATION_BLOCK='\n\n    # FOUNDATION 3.7 - Autonomous Property Brain Teacher\n    # Routine message labeling is automated. Human review is exception-only.\n    # No production/WhatsApp/Gold mutations.\n    try:\n        if _route_exists(app, "/api/property-brain/autonomous-v370/status"):\n            result["autonomous_v370"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v370","error":None}\n        else:\n            import alliance_autonomous_property_brain_v370 as autonomous_v370\n            result["autonomous_v370"] = {**autonomous_v370.register(core), "error": None}\n    except Exception as exc:\n        result["autonomous_v370"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v370","fail_safe":True}\n'

def main():
    root=Path(__file__).resolve().parent
    registrar=root/REGISTRAR
    module_path=root/MODULE_NAME
    if not registrar.exists(): raise SystemExit(f"ERROR: {REGISTRAR} not found")
    rt=registrar.read_text(encoding="utf-8")
    for req in ("FOUNDATION 3.6 - blind failure learning","alliance_blind_failure_learning_v360","return result"):
        if req not in rt: raise SystemExit(f"ERROR: expected 3.6 baseline marker missing: {req}")
    mt=base64.b64decode(MODULE_B64).decode("utf-8")
    compile(mt,MODULE_NAME,"exec")
    backup=None
    if MARKER not in rt:
        backup=root/f"{REGISTRAR}.before-v370-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
        shutil.copy2(registrar,backup)
        needle="\n    return result"
        pos=rt.rfind(needle)
        if pos<0: raise SystemExit("ERROR: registrar anchor not found")
        rt=rt[:pos]+REGISTRATION_BLOCK+rt[pos:]
    compile(rt,REGISTRAR,"exec")
    module_path.write_text(mt,encoding="utf-8")
    registrar.write_text(rt,encoding="utf-8")
    compile(module_path.read_text(encoding="utf-8"),str(module_path),"exec")
    compile(registrar.read_text(encoding="utf-8"),str(registrar),"exec")
    print("Alliance Property Brain 3.7 installed successfully")
    print("Dashboard: /property-brain/autonomous-v370")
    print("Routine manual labeling: STOPPED")
    print("Automation interval: 15 minutes default")
    print("Human review: exceptions only + periodic QA")
    print("Production/WhatsApp/Gold mutations: 0")
    if backup: print("Backup:",backup)

if __name__=="__main__": main()
